def slugify(text: str, *, separator: str = "-") -> str:
    """Lowercase text and join its words with `separator`."""
    return separator.join(text.lower().split())


def truncate(text: str, width: int = 80, placeholder: str = "…") -> str:
    """Shorten text to at most `width` characters."""
    return text if len(text) <= width else text[: width - len(placeholder)] + placeholder

